#include "../src/game/stage2_extra_projectiles.hpp"
#include "../src/game/stage_scene.hpp"
#include <cassert>
int main(int argc,char**argv){assert(argc==2);shin::AssetStore a(argv[1]);shin::ResourceArchive archive(argv[1]);shin::game::StageScene scene;scene.load(archive,1);shin::game::Stage2ExtraProjectiles shots(a,scene.map,scene.collision_blocks);shin::IndexedSurface f(640,480);shots.spawn(100,100,9,-7);assert(shots.targets[0].kind==0x5d);shots.tick(0,0,f);assert(shots.targets[0].at(4)==100);shots.update(shots.targets[0],0,0,f);assert(shots.targets[0].at(4)==97&&shots.targets[0].at(8)==94);assert(shots.targets[0].at(0x68)==0);shots.targets[0].at(0x58)=2;shots.update(shots.targets[0],0,0,f);assert(shots.targets[0].at(4)==100&&shots.targets[0].at(0x68)==1);shots.targets[0].at(0x58)=3;shots.targets[0].at(0x18)=0;shots.targets[0].at(0x1c)=0;shots.update(shots.targets[0],0,0,f);assert(shots.targets[0].at(0x54)==-9);shots.targets[0].at(0x18)=1;shots.targets[0].at(0x1c)=0;shots.update(shots.targets[0],0,0,f);assert(shots.targets[0].state==2);return 0;}
